def ant(grid, column, row, n, direction=0):
    rows, cols = len(grid), max(len(row) for row in grid)

    # Expand grid if necessary
    for i in range(rows):
        if len(grid[i]) < cols:
            grid[i] += [0] * (cols - len(grid[i]))
    grid += [[0] * cols for _ in range(n + 1 - len(grid))]

    while n > 0:
        if grid[row][column] == 0:
            direction = (direction + 3) % 4  # Turn left
        else:
            direction = (direction + 1) % 4  # Turn right

        grid[row][column] = 1 - grid[row][column]  # Flip color

        if direction == 0:
            row -= 1  # Move north
        elif direction == 1:
            column += 1  # Move east
        elif direction == 2:
            row += 1  # Move south
        else:
            column -= 1  # Move west

        # Expand grid if necessary
        if row < 0:
            grid.insert(0, [0] * cols)
            row = 0
        if column < 0:
            for i in range(len(grid)):
                grid[i].insert(0, 0)
            column = 0
        if row >= len(grid):
            grid.append([0] * cols)
        if column >= len(grid[0]):
            for i in range(len(grid)):
                grid[i].append(0)

        n -= 1

    return grid
