            if len(grid) <= y:
                grid.append([0] * cols)
            grid[y][x] = value

    directions = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # N, E, S, W

    for _ in range(n):
        dx, dy = directions[direction]
        set_value(column + dx, row + dy, 1 - get_value(column + dx, row + dy))
        column, row = column + dx, row + dy
        direction = (direction + 1) % 4 if get_value(column + dx, row + dy) == 0 else (direction + 3) % 4

    return grid
